        {"type": "choice", "topic": "Đọc hiểu", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Con vật nào cất tiếng gáy lanh lảnh ở đầu bản?", "options": ["A. Con gà rừng", "B. Con chim cuốc", "C. Con ve", "D. Con gà trống"], "answer": "D. Con gà trống", "explanation": "Bài viết: “Bỗng một con gà trống vỗ cánh phành phạch và cất tiếng gáy lanh lảnh ở đầu bản.”"},
        {"type": "choice", "topic": "Đọc hiểu", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Dòng nào nêu đúng tên các con vật được tả trong bài?", "options": ["A. Gà trống, gà mái, ve, chim cuốc", "B. Gà trống, gà rừng, ve, chim cuốc", "C. Gà trống, gà mái, gà rừng, chim cuốc", "D. Gà trống, chim sẻ, gà rừng, ve"], "answer": "B. Gà trống, gà rừng, ve, chim cuốc", "explanation": "Bài có gà trống, gà rừng, ve và chim cuốc. Bài không nhắc đến gà mái hay chim sẻ."},
        {"type": "choice", "topic": "Đọc hiểu", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Tiếng gà gáy được tả bằng những từ ngữ nào?", "options": ["A. phành phạch, râm ran, te te", "B. lanh lảnh, râm ran, te te", "C. lanh lảnh, phành phạch, te te", "D. rì rầm, lanh lảnh, ra rả"], "answer": "B. lanh lảnh, râm ran, te te", "explanation": "Gà trống gáy “lanh lảnh”, tiếng gà gáy khắp thung lũng “râm ran”, gà rừng gáy “te te”. “phành phạch” là tiếng vỗ cánh."},
        {"type": "choice", "topic": "Đọc hiểu", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Tiếng ve được tả như thế nào?", "options": ["A. Ve kêu râm ran khắp thung lũng", "B. Ve kêu đều đều vọng vào từ suối", "C. Ve kêu te te trên mấy ngọn núi", "D. Ve đua nhau kêu ra rả trên cây cao"], "answer": "D. Ve đua nhau kêu ra rả trên cây cao", "explanation": "Bài viết: “Trên mấy cây cao cạnh nhà, ve đua nhau kêu ra rả.” “Râm ran”, “te te” là tiếng gà gáy; “đều đều” là tiếng chim cuốc ngoài suối."},
