        {"type": "choice", "topic": "Kiểu câu", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Câu “Bộ lông chú hươu xác xơ.” thuộc kiểu câu nào?", "options": ["A. Câu giới thiệu", "B. Câu nêu hoạt động", "C. Câu nêu đặc điểm", "D. Câu hỏi"], "answer": "C. Câu nêu đặc điểm", "explanation": "“xác xơ” cho biết bộ lông thế nào, nên đây là câu nêu đặc điểm."},
        {"type": "choice", "topic": "Kiểu câu", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Câu nào dưới đây là câu nêu hoạt động?", "options": ["A. Hươu là con vật hiền lành và nhanh nhẹn.", "B. Bầy hươu gặm cỏ bên dòng suối.", "C. Gạc hươu rất cứng.", "D. Bộ lông hươu màu nâu."], "answer": "B. Bầy hươu gặm cỏ bên dòng suối.", "explanation": "“gặm cỏ” là việc bầy hươu đang làm, nên đây là câu nêu hoạt động. Câu “Hươu là…” là câu giới thiệu; hai câu còn lại nêu đặc điểm."},
        {"type": "choice", "topic": "Chính tả dấu thanh", "section_start": "III. CHÍNH TẢ", "section_instruction": "Chọn câu trả lời đúng.", "passage_text": None, "q": "Từ nào viết đúng chính tả?", "options": ["A. tập tểnh", "B. tặp tễnh", "C. tập tệnh", "D. tập tễnh"], "answer": "D. tập tễnh", "explanation": "Từ đúng là “tập tễnh” (dấu ngã), như trong bài: “bước đi tập tễnh”."},
        {"type": "choice", "topic": "Chính tả g/gh", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Từ nào viết SAI chính tả?", "options": ["A. ghi nhớ", "B. ghọn gàng", "C. gặm cỏ", "D. gạc hươu"], "answer": "B. ghọn gàng", "explanation": "Chỉ viết “gh” trước i, e, ê. Trước “o” phải viết “g”: đúng là “gọn gàng”."},
        {"type": "choice", "topic": "Chính tả ch/tr", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Chọn từ viết đúng để điền vào chỗ trống: “Chú hươu lấy gạc cắt rụng mấy cái … .”", "options": ["A. trồi non", "B. chồi nom", "C. chồi non", "D. trồi nom"], "answer": "C. chồi non", "explanation": "Mầm non mới nhú của cây là “chồi non” (ch, vần on), như trong bài."},
        {"type": "choice", "topic": "Viết đoạn văn", "section_start": "IV. VIẾT", "section_instruction": "Chọn câu trả lời đúng.", "passage_text": None, "q": "Em viết đoạn văn kể về một giờ ra chơi. Câu nào phù hợp nhất để mở đầu?", "options": ["A. Tùng! Tùng! Tùng! Trống báo giờ ra chơi đã vang lên.", "B. Hết giờ ra chơi, chúng em lại vui vẻ vào lớp học.", "C. Các bạn nữ chơi nhảy dây, còn các bạn nam chơi đá cầu.", "D. Giờ học Toán hôm nay, cô dạy chúng em phép cộng."], "answer": "A. Tùng! Tùng! Tùng! Trống báo giờ ra chơi đã vang lên.", "explanation": "Câu mở đầu cần báo hiệu giờ ra chơi bắt đầu (câu A). Câu B kể lúc hết giờ, hợp để kết thúc; câu C kể trò chơi, nên đặt ở giữa đoạn; câu D nói về giờ học Toán, không phải giờ ra chơi."},
        {"type": "choice", "topic": "Viết đoạn văn", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Sắp xếp các câu sau thành đoạn văn hợp lí:\n(1) Các bạn nữ chơi nhảy dây, các bạn nam chơi đá cầu.\n(2) Tiếng trống vang lên, chúng em ùa ra sân.\n(3) Hết giờ ra chơi, chúng em vui vẻ vào lớp học tiếp.\n(4) Sân trường bỗng trở nên rộn ràng.", "options": ["A. 1 – 2 – 4 – 3", "B. 3 – 2 – 4 – 1", "C. 2 – 3 – 1 – 4", "D. 2 – 4 – 1 – 3"], "answer": "D. 2 – 4 – 1 – 3", "explanation": "Trống báo, học sinh ra sân (2), sân trường rộn ràng (4), các bạn vui chơi (1), hết giờ vào lớp (3)."},
