        {"type": "choice", "topic": "Chính tả dấu hỏi/ngã", "section_start": None, "section_instruction": None, "passage_text": None, "q": "Từ nào viết đúng chính tả?", "options": ["A. mãnh khảnh", "B. mảnh khãnh", "C. mãnh khãnh", "D. mảnh khảnh"], "answer": "D. mảnh khảnh", "explanation": "Viết đúng là \"mảnh khảnh\": cả hai tiếng đều mang dấu hỏi."},
